import boto3

def query_error_logs(log_group_name, query_string):
    client = boto3.client('logs')
    response = client.start_query(
        logGroupName=log_group_name,
        queryString=query_string,
        limit=100
    )
    query_id = response['queryId']
    while True:
        response = client.get_query_results(queryId=query_id)
        if response['status'] == 'Complete':
            return response['results']

if __name__ == '__main__':
    log_group_name = 'my-log-group'
    query_string = 'fields @message | filter @message like /error/ | sort @timestamp desc | limit 10'
    results = query_error_logs(log_group_name, query_string)
    for result in results:
        print(result)

import os
import boto3

def get_client(service_name):
    return boto3.client(
        service_name,
        aws_access_key_id=os.getenv('AWS_ACCESS_KEY_ID'),
        aws_secret_access_key=os.getenv('AWS_SECRET_ACCESS_KEY'),
        region_name=os.getenv('AWS_REGION')
    )

import json

def normalize_log_event(log_event):
    return {
        'timestamp': int(log_event['timestamp'] * 1000),
        'message': json.dumps(log_event['message'])
    }

import boto3

def check_log_message_safety(log_message):
    comprehend = boto3.client('comprehend')
    response = comprehend.detect_toxic_content(
        TextSegments=[{
            'Text': log_message
        }],
        LanguageCode='en'
    )
    return response['Results'][0]['Toxicity']

if __name__ == '__main__':
    log_message = 'This is a sample log message.'
    safety_score = check_log_message_safety(log_message)
    print(safety_score)

import boto3

def embed_log_message(log_message):
    sagemaker = boto3.client('sagemaker-runtime')
    response = sagemaker.invoke_endpoint(
        EndpointName='my-sagemaker-endpoint',
        ContentType='text/plain',
        Body=log_message
    )
    return response['Body'].read()

if __name__ == '__main__':
    log_message = 'This is a sample log message.'
    embedding = embed_log_message(log_message)
    print(embedding)
